'use client';

import { useSavingsData } from '../hooks/data';
import { Card } from '../components/ui/card';
import { Badge } from '../components/ui/badge';
import { motion, useInView, AnimatePresence } from 'framer-motion';
import { useState, useEffect, useRef, useMemo } from 'react';

// --- prefers-reduced-motion hook ---
function usePrefersReducedMotion() {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  useEffect(() => {
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(media.matches);
    const handler = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    media.addEventListener('change', handler);
    return () => media.removeEventListener('change', handler);
  }, []);
  return prefersReducedMotion;
}

export default function Home() {
  // --- All hooks first ---
  const { data, isLoading, isError } = useSavingsData();
  const prefersReducedMotion = usePrefersReducedMotion();

  const sectionRef = useRef<HTMLElement>(null);
  const isInView = useInView(sectionRef, { once: true, amount: 0.1 });

  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  useEffect(() => {
    const stored = localStorage.getItem('theme') as 'light' | 'dark' | null;
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const initial = stored || (prefersDark ? 'dark' : 'light');
    setTheme(initial);
    document.documentElement.setAttribute('data-theme', initial);
  }, []);

  // Stats (safe to compute before data is ready, they'll be zero)
  const totalMetrics = data?.metrics.length || 0;
  const highImpactCount = data?.metrics.filter(m => m.impactLevel === 'High').length || 0;
  const averageSavings = totalMetrics ? Math.round((data?.totalSavings || 0) / totalMetrics) : 0;

  const categoryTotals = useMemo(() => {
    if (!data) return new Map<string, number>();
    const map = new Map<string, number>();
    data.metrics.forEach(m => {
      const prev = map.get(m.category) || 0;
      map.set(m.category, prev + m.savingsAmount);
    });
    return map;
  }, [data]);

  const impactCounts = useMemo(() => {
    if (!data) return { High: 0, Medium: 0, Low: 0 };
    return data.metrics.reduce((acc, m) => {
      acc[m.impactLevel] = (acc[m.impactLevel] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);
  }, [data]);

  // --- Early returns (after all hooks) ---
  if (isLoading) {
    return (
      <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-50 to-slate-100 dark:from-[#1e1718] dark:to-[#021022]">
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-center space-y-4"
        >
          <div className="w-12 h-12 border-4 border-emerald-600 border-t-transparent rounded-full mx-auto animate-spin" />
          <p className="text-lg font-medium text-slate-700 dark:text-slate-300">Caricamento dati...</p>
        </motion.div>
      </main>
    );
  }

  if (isError || !data) {
    return (
      <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-50 to-slate-100 dark:from-[#1e1718] dark:to-[#021022]">
        <div className="text-center space-y-4 max-w-md p-6 bg-white/80 dark:bg-[#1d232a]/80 backdrop-blur rounded-2xl shadow-xl">
          <div className="text-4xl">⚠️</div>
          <h2 className="text-xl font-semibold text-slate-800 dark:text-slate-200">Errore di caricamento</h2>
          <p className="text-slate-600 dark:text-slate-400">Si è verificato un errore nel recupero dei dati.</p>
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => window.location.reload()}
            className="px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors shadow-lg"
          >
            Riprova
          </motion.button>
        </div>
      </main>
    );
  }

  // --- Animated counter (effect only runs when data is ready) ---
  const [displayTotal, setDisplayTotal] = useState(0);
  useEffect(() => {
    if (prefersReducedMotion) {
      setDisplayTotal(data.totalSavings);
      return;
    }
    let start = 0;
    const duration = 1500;
    const stepTime = 16;
    const total = data.totalSavings;
    const steps = duration / stepTime;
    const increment = total / steps;
    let current = 0;
    const timer = setInterval(() => {
      current += increment;
      if (current >= total) {
        setDisplayTotal(total);
        clearInterval(timer);
      } else {
        setDisplayTotal(Math.round(current));
      }
    }, stepTime);
    return () => clearInterval(timer);
  }, [data.totalSavings, prefersReducedMotion]);

  // --- Container query CSS (inline) ---
  const containerQueryStyles = `
    .card-container {
      container-type: inline-size;
    }
    .card-container .card-content {
      padding: 1rem;
    }
    @container (min-width: 300px) {
      .card-container .card-content {
        padding: 1.25rem;
      }
    }
    @container (min-width: 400px) {
      .card-container .card-content {
        padding: 1.5rem;
      }
    }
    .card-container:has(.badge-alert) {
      border-color: color-mix(in srgb, var(--color-badge-alert-text) 30%, transparent);
      box-shadow: 0 0 0 1px var(--color-badge-alert-text);
    }
    @media (prefers-reduced-motion: reduce) {
      .motion-safe {
        animation: none !important;
        transition: none !important;
      }
    }
  `;

  // --- Theme toggle function ---
  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light';
    setTheme(newTheme);
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('theme', newTheme);
  };

  return (
    <main className="min-h-screen relative overflow-hidden bg-gradient-to-br from-slate-50 via-white to-slate-100 dark:from-[#1e1718] dark:via-[#1d232a] dark:to-[#021022] transition-colors duration-500">
      <style>{containerQueryStyles}</style>

      {/* Decorative background blobs */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <motion.div
          className="absolute -top-40 -right-40 w-96 h-96 bg-emerald-400/20 dark:bg-emerald-500/10 rounded-full blur-3xl"
          animate={{ x: [0, 40, 0], y: [0, -30, 0] }}
          transition={{ duration: 12, repeat: Infinity, ease: "easeInOut" }}
        />
        <motion.div
          className="absolute -bottom-40 -left-40 w-80 h-80 bg-blue-400/20 dark:bg-blue-500/10 rounded-full blur-3xl"
          animate={{ x: [0, -50, 0], y: [0, 40, 0] }}
          transition={{ duration: 15, repeat: Infinity, ease: "easeInOut" }}
        />
      </div>

      <div className="relative z-10 max-w-7xl mx-auto p-4 md:p-6 space-y-6">
        {/* --- Header (load animation only) --- */}
        <motion.header
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="bg-white/70 dark:bg-[#1d232a]/70 backdrop-blur-xl rounded-2xl shadow-lg border border-white/20 dark:border-slate-700/30 p-4 md:p-6"
        >
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-xl shadow-inner">
                <svg className="w-6 h-6 text-emerald-600 dark:text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                </svg>
              </div>
              <div>
                <h1 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-emerald-600 to-blue-600 dark:from-emerald-400 dark:to-blue-400 bg-clip-text text-transparent">
                  Cloud Savings Dashboard
                </h1>
                <p className="text-sm text-slate-600 dark:text-slate-400">Ottimizzazione dei costi e sprechi</p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              {/* Theme toggle */}
              <button
                onClick={toggleTheme}
                className="p-2 rounded-full bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 transition-colors shadow-inner"
                aria-label="Toggle theme"
              >
                {theme === 'light' ? (
                  <svg className="w-5 h-5 text-slate-800" fill="currentColor" viewBox="0 0 20 20">
                    <path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z" />
                  </svg>
                ) : (
                  <svg className="w-5 h-5 text-yellow-300" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z" clipRule="evenodd" />
                  </svg>
                )}
              </button>

              {/* Total Savings (counter) */}
              <div className="bg-gradient-to-r from-emerald-600 to-blue-600 rounded-xl px-4 py-2 text-white shadow-lg flex items-center gap-3">
                <div className="text-center">
                  <span className="text-[10px] uppercase tracking-wider block opacity-90">Risparmio Totale</span>
                  <span className="text-xl font-bold">€{displayTotal.toLocaleString()}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Stats bar */}
          <div className="mt-5 grid grid-cols-3 gap-2 pt-4 border-t border-slate-200 dark:border-slate-700/50">
            <div className="text-center">
              <div className="text-2xl font-bold text-slate-800 dark:text-slate-200">{totalMetrics}</div>
              <div className="text-[10px] text-slate-500 dark:text-slate-400">Metriche</div>
            </div>
            <div className="text-center border-x border-slate-200 dark:border-slate-700/50">
              <div className="text-2xl font-bold text-amber-600 dark:text-amber-400">{highImpactCount}</div>
              <div className="text-[10px] text-slate-500 dark:text-slate-400">Alto Impatto</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600 dark:text-green-400">€{averageSavings.toLocaleString()}</div>
              <div className="text-[10px] text-slate-500 dark:text-slate-400">Media</div>
            </div>
          </div>
        </motion.header>

        {/* --- Mini charts (scroll‑triggered) --- */}
        <motion.section
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.6 }}
          className="grid grid-cols-1 md:grid-cols-2 gap-4"
        >
          <Card className="p-4 bg-white/60 dark:bg-[#1d232a]/60 backdrop-blur-md border-white/20 dark:border-slate-700/30">
            <h3 className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">Risparmio per Categoria</h3>
            <div className="space-y-2">
              {Array.from(categoryTotals.entries()).map(([category, total]) => {
                const max = Math.max(...Array.from(categoryTotals.values()));
                const pct = max > 0 ? (total / max) * 100 : 0;
                return (
                  <div key={category} className="flex items-center gap-2">
                    <span className="text-xs font-mono text-slate-600 dark:text-slate-400 w-24 truncate">{category}</span>
                    <div className="flex-1 h-2 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                      <motion.div
                        initial={{ width: 0 }}
                        whileInView={{ width: `${pct}%` }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.8, delay: 0.1 }}
                        className="h-full bg-gradient-to-r from-emerald-400 to-blue-500 rounded-full"
                      />
                    </div>
                    <span className="text-xs font-medium text-slate-700 dark:text-slate-300 w-14 text-right">€{total.toLocaleString()}</span>
                  </div>
                );
              })}
            </div>
          </Card>

          <Card className="p-4 bg-white/60 dark:bg-[#1d232a]/60 backdrop-blur-md border-white/20 dark:border-slate-700/30">
            <h3 className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">Distribuzione Impatto</h3>
            <div className="space-y-2">
              {Object.entries(impactCounts).map(([level, count]) => {
                const total = Object.values(impactCounts).reduce((a, b) => a + b, 0);
                const pct = total > 0 ? (count / total) * 100 : 0;
                const colors = {
                  High: 'from-red-400 to-red-500',
                  Medium: 'from-amber-400 to-amber-500',
                  Low: 'from-emerald-400 to-emerald-500'
                };
                return (
                  <div key={level} className="flex items-center gap-2">
                    <span className="text-xs font-mono text-slate-600 dark:text-slate-400 w-16">{level}</span>
                    <div className="flex-1 h-2 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                      <motion.div
                        initial={{ width: 0 }}
                        whileInView={{ width: `${pct}%` }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.8, delay: 0.1 }}
                        className={`h-full bg-gradient-to-r ${colors[level as keyof typeof colors]} rounded-full`}
                      />
                    </div>
                    <span className="text-xs font-medium text-slate-700 dark:text-slate-300 w-12 text-right">{count}</span>
                  </div>
                );
              })}
            </div>
          </Card>
        </motion.section>

        {/* --- Main feature: cards with scroll‑triggered stagger --- */}
        <motion.section
          ref={sectionRef}
          initial="hidden"
          animate={isInView ? "visible" : "hidden"}
          variants={{
            hidden: { opacity: 0 },
            visible: {
              opacity: 1,
              transition: {
                staggerChildren: 0.08,
                delayChildren: 0.2,
              },
            },
          }}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4"
        >
          <AnimatePresence>
            {data.metrics.map((metric) => (
              <motion.div
                key={metric.id}
                variants={{
                  hidden: { opacity: 0, y: 30 },
                  visible: {
                    opacity: 1,
                    y: 0,
                    transition: {
                      type: prefersReducedMotion ? "tween" : "spring",
                      stiffness: 100,
                      damping: 12,
                    },
                  },
                }}
                whileHover={prefersReducedMotion ? {} : {
                  scale: 1.03,
                  y: -4,
                  transition: { type: "spring", stiffness: 300, damping: 20 },
                }}
                className="card-container h-full"
              >
                <Card className="h-full flex flex-col justify-between space-y-3 card-content bg-white/70 dark:bg-[#1d232a]/70 backdrop-blur-md border-white/20 dark:border-slate-700/30 shadow-lg hover:shadow-xl transition-all duration-300">
                  <div>
                    <div className="flex justify-between items-start mb-2">
                      <span className="text-[10px] font-mono px-2 py-0.5 bg-slate-100/80 dark:bg-slate-700/50 rounded text-slate-600 dark:text-slate-400">
                        {metric.category}
                      </span>
                      <Badge
                        variant={metric.impactLevel === 'High' ? 'alert' : 'brand'}
                        className={metric.impactLevel === 'High' ? 'badge-alert' : ''}
                      >
                        {metric.impactLevel === 'High' ? '⚠ ' : '✓ '}
                        {metric.impactLevel} Impact
                      </Badge>
                    </div>
                    <h2 className="text-base font-semibold mb-1 text-slate-800 dark:text-slate-200">
                      {metric.title}
                    </h2>
                    <p className="text-sm opacity-80 line-clamp-2 text-slate-600 dark:text-slate-400">
                      {metric.description}
                    </p>
                  </div>

                  <div className="pt-3 border-t border-slate-200 dark:border-slate-700/50 flex justify-between items-center">
                    <span className="text-xs opacity-70 text-slate-500 dark:text-slate-400">Risparmio:</span>
                    <motion.span
                      initial={{ opacity: 0, x: 20 }}
                      whileInView={{ opacity: 1, x: 0 }}
                      viewport={{ once: true }}
                      transition={{ delay: 0.3 }}
                      className="text-base font-bold text-emerald-600 dark:text-emerald-400"
                    >
                      €{metric.savingsAmount.toLocaleString()}
                    </motion.span>
                  </div>
                </Card>
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.section>
      </div>
    </main>
  );
}